class Problem {
public:
	int l = 0;
	int n = 0;
	int s = 0;
	int poss[MAX_N][2] = {};

	Problem() {
	}

	void load(istream& in) {
		in >> l >> n >> s;
		repn(i) {
			in >> poss[i][0] >> poss[i][1];
		}
	}
};

class Server {
private:
public:
	Problem p;
	int seed = 0;
	int count = 0;
	int l = 0;
	int n = 0;
	int s = 0;
	int as[MAX_N] = {};
	int fs[MAX_Q] = {};
	int temps[MAX_L][MAX_L] = {};
	bool done = false;

	ll setupCost = 0;
	ll measureCost = 0;
	int es[MAX_N] = {};
	int incorrects = 0;
	ll score = 0;

	Server() {
	}

	void load(istream& in) {
		p.load(in);
		l = p.l;
		n = p.n;
		s = p.s;
		repn(i) {
			in >> as[i];
		}
		rep0(i, MAX_Q) {
			in >> fs[i];
		}
		// trace("loaded! ", l, " ", n, " ", s);
	}

	void load(int seed) {
		// trace("setting up seed=", seed, "...");
		this->seed = seed;
		string data = readText("in/"s +
		    (seed < 10            ? "000"
		            : seed < 100  ? "00"
		            : seed < 1000 ? "0"
		                          : "") +
		    to_string(seed) + ".txt")
		                  .first;
		istringstream in(data);
		isLocal = true;
		load(in);
	}

	void initialOutput(ostream& out) {
		out << l << " " << n << " " << s << endl;
		repn(i) {
			out << p.poss[i][0] << " " << p.poss[i][1] << endl;
		}
	}

	void initialInput(istream& in) {
		rep2() {
			in >> temps[i][j];
			assert(temps[i][j] >= 0 && temps[i][j] <= 1000);
		}
		setupCost = 0;
		rep2() {
			int di = temps[i][j] - temps[(i + 1) % l][j];
			int dj = temps[i][j] - temps[i][(j + 1) % l];
			setupCost += di * di + dj * dj;
		}
	}

	void query(istream& in, ostream& out) {
		while (in.peek() == '#') {
			string dummy;
			getline(in, dummy);
		}
		int i, dy, dx;
		in >> i >> dy >> dx;
		if (i == -1 && dy == -1 && dx == -1) {
			incorrects = 0;
			repn(i) {
				in >> es[i];
				incorrects += es[i] != as[i];
			}
			computeScore();
			done = true;
			return;
		}
		assert(i >= 0 && i < n);
		assert(dy >= -l && dy <= l);
		assert(dx >= -l && dx <= l);
		int y = p.poss[as[i]][0];
		int x = p.poss[as[i]][1];
		int p = temps[(y + dy + l) % l][(x + dx + l) % l];
		int res = clamp(p + fs[count], 0, 1000);
		measureCost += 100 * (10 + abs(dy) + abs(dx));
		out << res << endl;
		count++;
	}

	void dump() {
		assert(done);
		trace("  finished! ", count, ", ", n - incorrects, ", ", incorrects, ", ", score);
	}

private:
	void computeScore() {
		score = (ll) ceil(1e14 * pow(0.8, incorrects) / (setupCost + measureCost + 1e5));
	}
};

class PoissonSolver {
private:
public:
	double temps[MAX_L][MAX_L] = {};
	bool fixed[MAX_L][MAX_L] = {};

	PoissonSolver() {
	}

	double solve(int l, int iter, bool print = true) {
		int st = timer();
		double pcost = 0;
		rep0(t, iter) {
			double cost = 0;
			rep2() {
				if (fixed[i][j])
					continue;
				double diff = (temps[(i + l - 1) % l][j] + temps[(i + 1) % l][j] + temps[i][(j + l - 1) % l] +
				                  temps[i][(j + 1) % l]) *
				        0.25 -
				    temps[i][j];
				temps[i][j] += diff * 1.6; // SOR
			}
			rep2() {
				double di = temps[i][j] - temps[(i + 1) % l][j];
				double dj = temps[i][j] - temps[i][(j + 1) % l];
				cost += di * di + dj * dj;
			}
			if (print && t % 50 == 0)
				trace("cost: ", cost);
			if (abs(pcost - cost) < 5e-5)
				break;
			pcost = cost;
		}
		int en = timer();
		if (print)
			trace("poisson: ", en - st, " ms");
		return pcost;
	}
};

