double likelihood(int si, int trueV, int observedV) {
	assert(trueV >= 0 && trueV <= 1000);
	assert(observedV >= 0 && observedV <= 1000);
	if (observedV == 0) {
		// P(-trueV or less) = P(trueV or greater)
		return PROBS[si][trueV];
	}
	if (observedV == 1000) {
		// P(1000 - trueV or greater)
		return PROBS[si][1000 - trueV];
	}
	int diff = abs(trueV - observedV);
	// P(diff) = P(diff or greater) - P(diff + 1 or greater)
	return PROBS[si][diff] - PROBS[si][diff + 1];
}

double distinguishability(int s, int diff) {
	return 1 - exp(-1.0 * (diff * diff) / (s * s));
}

constexpr double MIN_PROB = 1e-6;

class Distribution {
private:
public:
	int n = 0;
	double ps[MAX_N] = {};
	pdi sorted[MAX_N] = {};
	int best = 0;
	bool uniform = false;
	double maxP = 0;

	Distribution() {
	}

	void setUniform(int n) {
		this->n = n;
		repn(i) {
			ps[i] = 1;
		}
		normalize();
		uniform = true;
	}

	void setLikelihood(int n, int si, int trueVs[MAX_N], int observedV) {
		this->n = n;
		repn(i) {
			ps[i] = likelihood(si, trueVs[i], observedV);
		}
	}

	void apply(Distribution& likelihood) {
		assert(n == likelihood.n);
		double sum = 0;
		repn(i) {
			ps[i] *= likelihood.ps[i];
			sum += ps[i];
		}
		if (sum == 0) {
			trace("prob degenerated");
			repn(i) {
				ps[i] = likelihood.ps[i];
			}
		}
		normalize();
	}

	void normalize() {
		double sum = 0;
		repn(i) {
			ps[i] = max(MIN_PROB, ps[i]);
			sum += ps[i];
		}
		double invSum = 1 / sum;
		uniform = false;
		maxP = 0;
		best = 0;
		repn(i) {
			ps[i] *= invSum;
			if (ps[i] > maxP) {
				maxP = ps[i];
				best = i;
			}
			sorted[i] = pdi(ps[i], i);
		}
	}

	void sort() {
		::sort(sorted, sorted + n, greater<pdi>());
	}
};

